/**
 * VitalSync i18n — Supported languages: en, es, fr, zh
 * Auto-detected from device locale via expo-localization.
 * Users can override via Settings; the override is persisted to AsyncStorage
 * and loaded at app start via initLang().
 */
import { getLocales } from "expo-localization";
import AsyncStorage from "@react-native-async-storage/async-storage";
import { safeSetItem } from '@/lib/safe-async-storage';

/** Static languages with built-in dictionaries. */
export type StaticLang = "en" | "es" | "fr" | "zh" | "pt" | "ar" | "hi" | "de" | "sw" | "ja";

/** Any supported language code (static built-ins + Smart-translated languages). */
export type Lang = StaticLang | string;

export const LANG_OVERRIDE_KEY = "@vsht:lang_override";

/** Module-level override — set by initLang() at startup and setLangOverride() at runtime. */
let _langOverride: string | null = null;

/** Listeners notified when the language changes. */
const _listeners = new Set<() => void>();

export function addLangListener(fn: () => void) {
  _listeners.add(fn);
  return () => _listeners.delete(fn);
}

function _notifyListeners() {
  _listeners.forEach((fn) => fn());
}

/** Call once at app start (e.g. in _layout.tsx) to load the persisted override. */
export async function initLang(): Promise<void> {
  try {
    const stored = await AsyncStorage.getItem(LANG_OVERRIDE_KEY);
    // Accept any non-empty BCP-47 language tag (2–10 chars)
    if (stored && stored.length >= 2 && stored.length <= 10) {
      _langOverride = stored;
    }
  } catch (_unused) {
    // ignore
  }
}

/** Persist and apply a manual language override. Pass null to reset to device locale. */
export async function setLangOverride(lang: string | null): Promise<void> {
  _langOverride = lang;
  try {
    if (lang) {
      await safeSetItem(LANG_OVERRIDE_KEY, lang);
    } else {
      await AsyncStorage.removeItem(LANG_OVERRIDE_KEY);
    }
  } catch (_unused) {
    // ignore
  }
  _notifyListeners();
}
/** In-memory preview language (non-persistent, cleared on app restart). */
let _previewLang: string | null = null;

/** Set a temporary preview language (shown in Settings language preview mode). */
export function setPreviewLang(lang: string | null): void {
  _previewLang = lang;
  _notifyListeners();
}

/** Get the current preview language (null if not previewing). */
export function getPreviewLang(): string | null {
  return _previewLang;
}



/** Returns the current language, respecting any manual override. */
export function detectLang(): string {
  if (_langOverride) return _langOverride;
  try {
    const tag = getLocales()[0]?.languageTag ?? "en";
    // Handle special cases first
    if (tag.startsWith("zh")) return "zh";
    if (tag.startsWith("no") || tag.startsWith("nb") || tag.startsWith("nn")) return "en";  // Norwegian removed, fall back to English
    // Extract base language code (e.g. 'fr-CA' -> 'fr')
    const base = tag.split('-')[0].toLowerCase();
    const supported: StaticLang[] = ["en", "es", "fr", "pt", "ar", "hi", "de", "sw", "ja"];
    if ((supported as string[]).includes(base)) return base;
  } catch (_unused) {
    // fallback
  }
  return "en";
}

/**
 * Clamp any language code to a StaticLang for indexing built-in dictionaries.
 * All 19 supported languages are now first-class; unknown codes fall back to English.
 */
export function toStaticLang(lang: string): StaticLang {
  const staticLangs: StaticLang[] = ["en", "es", "fr", "zh", "pt", "ar", "hi", "de", "sw", "ja"];
  const base = lang.split('-')[0] as StaticLang;
  if ((staticLangs as string[]).includes(base)) return base;
  return "en";
}

